@ParameterizedTest
// username candidates
@ValueSource(strings = { "sven", "!@$5:", "" })
void roundtrip(final String username) {
    var featureId = ApplicationFeatureId.fromIdentifier(Identifier.classIdentifier(LogicalType.fqcn(this.getClass())));
    var permissionsEvaluationService = mock(PermissionsEvaluationService.class);
    var permissions = List.of(new ApplicationPermissionValue(featureId, ApplicationPermissionRule.ALLOW, ApplicationPermissionMode.CHANGING));
    var user = mock(ApplicationUser.class);
    when(user.getUsername()).thenReturn(username);
    when(user.getPermissionSet()).thenReturn(new ApplicationPermissionValueSet(permissions, permissionsEvaluationService));
    var factoryService = MetaModelContext_forTesting.buildDefault().getFactoryService();
    var vm = UserPermissionViewModel.asViewModel(user, factoryService).apply(featureId);
    // when
    var memento = vm.viewModelMemento();
    var vmAfterRoundtrip = new UserPermissionViewModel(memento);
    // then
    assertEquals(username, vmAfterRoundtrip.getUsername());
}

